<?php

namespace Database\Seeders;

use App\Models\Quote;
use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;

class QuoteSeeder extends Seeder
{
    public function run(): void
    {
        $library = User::firstOrCreate(
            ['email' => 'library@wamda.test'],
            ['name' => 'مكتبة ومضة', 'password' => Str::random(40)],
        );

        $stamp = now()->subYear();

        foreach ($this->quotes() as [$category, $content, $author, $source, $meaning]) {
            $quote = new Quote([
                'category' => $category,
                'content' => $content,
                'author' => $author,
                'source' => $source ?: null,
                'meaning' => $meaning,
            ]);
            $quote->user()->associate($library);
            $quote->created_at = $stamp;
            $quote->updated_at = $stamp;
            $quote->save();
        }
    }

    private function quotes(): array
    {
        return [
            ['quotations', 'إن المسلمين قد أهلكهم التفرق في المذاهب والمشارب، فائتمروا في التآلف بينهم، والتعاون على مصالحهم ومنافعهم العامة المشتركة', 'الملك عبدالعزيز آل سعود', 'افتتاح المؤتمر الإسلامي في مكة، 1344هـ', 'يرى الملك عبدالعزيز أن ما أضعف المسلمين هو تفرّقهم واختلافهم، ويدعوهم إلى أن يتشاوروا فيما يؤلّف بينهم، ويتعاونوا على ما ينفعهم جميعاً.'],
            ['quotations', 'أنا مسلم وأحب جمع كلمة المسلمين، وليس أحب عندي من أن تجتمع كلمة المسلمين', 'الملك عبدالعزيز آل سعود', '', 'يعبّر عن أن أحبّ شيء إلى نفسه أن يتّحد المسلمون وتجتمع كلمتهم، وهو المبدأ الذي سار عليه في توحيد البلاد.'],
            ['quotations', 'البترول العربي ليس بأغلى من الدم العربي', 'الملك فيصل بن عبدالعزيز', 'حرب أكتوبر 1973', 'قالها الملك فيصل في حرب أكتوبر 1973 حين استُخدم النفط لنصرة العرب، ومعناها أن النفط مهما غلا ثمنه لا يساوي أرواح العرب ودماءهم.'],
            ['quotations', 'على شبابنا خاصة مسئوليات ضخمة، فهم سواعد البناء في يومنا وعقولنا المدبرة في غدنا', 'الملك فهد بن عبدالعزيز', '', 'يؤكد أن الشباب هم السواعد التي تبني الوطن اليوم، والعقول التي ستخطط لمستقبله غداً، ولذلك يحملون مسؤولية كبيرة.'],
            ['quotations', 'من نحن بدون المواطن السعودي', 'الملك عبدالله بن عبدالعزيز', '', 'سؤال يحمل جوابه في داخله: قيمة الدولة وقوتها بمواطنيها، فلا شيء للوطن من دون أبنائه.'],
            ['quotations', 'إن الموهبة دون اهتمام من أهلها أشبه ما تكون بالنبتة الصغيرة دون رعاية أو سقيا', 'الملك عبدالله بن عبدالعزيز', '', 'يشبّه الموهبة بنبتة صغيرة تذبل إذا لم تُسقَ، فالموهوب يحتاج من أهله ومجتمعه رعاية وتشجيعاً حتى تكبر موهبته.'],
            ['quotations', 'هدفي الأول أن تكون بلادنا نموذجاً ناجحاً ورائداً في العالم على كافة الأصعدة، وسأعمل معكم على تحقيق ذلك', 'خادم الحرمين الشريفين الملك سلمان بن عبدالعزيز', 'رؤية المملكة 2030', 'يعلن الملك سلمان أن غايته الأولى أن تكون المملكة قدوة ناجحة في كل المجالات، ويَعِد بأن يعمل مع المواطنين جنباً إلى جنب لتحقيق ذلك.'],
            ['quotations', 'همة السعوديين مثل جبل طويق، إنها لن تنكسر إلا إذا انهدّ هذا الجبل وتساوى بالأرض', 'ولي العهد الأمير محمد بن سلمان', 'مؤتمر الاستثمار، الرياض 2018', 'يشبّه عزيمة السعوديين بجبل طويق في قوته وثباته، فكما لا ينهار الجبل لا تنكسر همّتهم.'],
            ['quotations', 'مستقبل وطننا الذي نبنيه معاً، لن نقبل إلا أن نجعله في مقدمة دول العالم', 'ولي العهد الأمير محمد بن سلمان', 'رؤية المملكة 2030', 'بناء المستقبل عمل مشترك بين الجميع، والطموح ألّا يرضى الوطن بأقل من الصدارة بين دول العالم.'],
            ['quotations', 'سنعود إلى الإسلام الوسطي المعتدل والمنفتح على جميع الأديان', 'ولي العهد الأمير محمد بن سلمان', 'مبادرة مستقبل الاستثمار، الرياض 2017', 'يعبّر عن العودة إلى الإسلام المعتدل البعيد عن التشدد، المنفتح على العالم والمتعايش مع أتباع الأديان الأخرى.'],
            ['poetry', 'على قدر أهل العزم تأتي العزائم، وتأتي على قدر الكرام المكارم', 'المتنبي', '', 'العزائم الكبيرة تأتي على قدر أصحاب الإرادة القوية، والأفعال الكريمة على قدر كرم أصحابها؛ فكل إنسان ينال من العظمة بقدر همّته.'],
            ['poetry', 'ما كل ما يتمنى المرء يدركه، تجري الرياح بما لا تشتهي السفن', 'المتنبي', '', 'ليس كل ما يتمناه الإنسان يتحقق، فقد تأتي الأقدار بعكس ما يريد، كما تهبّ الرياح أحياناً بعكس ما تحتاجه السفن.'],
            ['poetry', 'إذا غامرتَ في شرفٍ مرومٍ، فلا تقنعْ بما دون النجوم', 'المتنبي', '', 'إذا سعيتَ إلى مجد تطلبه فلا ترضَ بالقليل، بل اجعل طموحك عالياً كالنجوم، فالمخاطرة في الأمر الصغير مثل المخاطرة في الأمر العظيم.'],
            ['poetry', 'أعزّ مكانٍ في الدنى سرجُ سابحٍ، وخيرُ جليسٍ في الزمان كتابُ', 'المتنبي', '', 'أعزّ مكان في الدنيا ظهر حصان سريع يعدو كأنه يسبح، وأفضل صديق يجالسه الإنسان في كل زمان هو الكتاب.'],
            ['poetry', 'إذا أنت أكرمت الكريم ملكته، وإن أنت أكرمت اللئيم تمردا', 'المتنبي', '', 'إذا أحسنت إلى الكريم كسبت قلبه وصار وفياً لك، أما اللئيم فإحسانك إليه يزيده تكبّراً وجحوداً.'],
            ['poetry', 'دع الأيام تفعل ما تشاء، وطب نفساً إذا حكم القضاء', 'الإمام الشافعي', '', 'يدعو إلى الرضا بما يقدّره الله، وأن يطمئن الإنسان ولا يقلق حين يقع ما لا يستطيع تغييره.'],
            ['poetry', 'نعيب زماننا والعيب فينا، وما لزماننا عيب سوانا', 'الإمام الشافعي', '', 'نلوم الزمن على ما يصيبنا، والحقيقة أن العيب في أنفسنا وأفعالنا، فالزمان لا عيب فيه إلا نحن.'],
            ['poetry', 'إذا الشعب يوماً أراد الحياة، فلا بدّ أن يستجيب القدر', 'أبو القاسم الشابي', 'إرادة الحياة', 'إذا عزم الشعب بصدق على أن يعيش حراً كريماً فلا بد أن تتحقق إرادته، فالإرادة القوية تصنع التغيير.'],
            ['poetry', 'وما نيل المطالب بالتمني، ولكن تؤخذ الدنيا غلابا', 'أحمد شوقي', '', 'الأهداف لا تتحقق بالأماني، بل تُنال بالجدّ والسعي والكفاح.'],
            ['poetry', 'وإنما الأمم الأخلاق ما بقيت، فإن همُ ذهبت أخلاقهم ذهبوا', 'أحمد شوقي', '', 'بقاء الأمم مرتبط بأخلاقها، فما دامت أخلاقها باقية بقيت، وإذا ضاعت أخلاقها ضاعت معها.'],
            ['poetry', 'تعبٌ كلها الحياة، فما أعجب إلا من راغبٍ في ازديادِ', 'أبو العلاء المعري', '', 'الحياة كلها مشقة وتعب، ولذلك يتعجب الشاعر ممن يتمنى أن يطول عمره فيها.'],
            ['poetry', 'وليلٍ كموج البحر أرخى سدوله، عليّ بأنواع الهموم ليبتلي', 'امرؤ القيس', 'المعلقة', 'يصف ليلاً طويلاً مظلماً مثل موج البحر، أرخى ستائره عليه بكل أنواع الهموم ليختبر صبره.'],
            ['poetry', 'ستبدي لك الأيام ما كنت جاهلاً، ويأتيك بالأخبار من لم تزوّدِ', 'طرفة بن العبد', 'المعلقة', 'الأيام ستكشف لك ما كنت تجهله، وستأتيك الأخبار من شخص لم تكلّفه بها ولم تعطه زاداً.'],
            ['poetry', 'ومهما تكن عند امرئٍ من خليقةٍ، وإن خالها تخفى على الناس تعلمِ', 'زهير بن أبي سلمى', 'المعلقة', 'مهما كان في الإنسان من طبع، وظن أنه يستطيع إخفاءه عن الناس، فإنه سيظهر ويعرفه الناس يوماً.'],
            ['poetry', 'سيذكرني قومي إذا جدّ جدّهم، وفي الليلة الظلماء يُفتقد البدرُ', 'أبو فراس الحمداني', '', 'قالها وهو في الأسر: سيتذكرني قومي حين تشتد عليهم الأمور، كما يُفتقد القمر في الليلة المظلمة.'],
            ['poetry', 'لا تسقني ماء الحياة بذلّةٍ، بل فاسقني بالعزّ كأس الحنظلِ', 'عنترة بن شداد', '', 'يفضّل الموت بعزّة على حياة فيها ذل، فكأس الحنظل المرّ مع العزة أحب إليه من ماء الحياة مع الإهانة.'],
            ['poetry', 'ولولا خلالٌ سنّها الشعر ما درى، بغاة العُلا من أين تؤتى المكارمُ', 'أبو تمام', '', 'لولا الصفات الحميدة التي مدحها الشعر وخلّدها، لما عرف طالبو المجد طريق المكارم؛ فالشعر يعلّم الناس معاني الكرم والمجد.'],
            ['poetry', 'أعطني الناي وغنِّ، فالغنا سرّ الوجود', 'جبران خليل جبران', 'المواكب', 'يدعو إلى الموسيقى والغناء، ويرى أن الغناء يحمل سرّ الوجود وجماله، وهو من قصيدة المواكب التي تمدح حياة الغاب البسيطة.'],
            ['literature', 'الصديق إنسان هو أنت إلا أنه غيرك', 'أبو حيان التوحيدي', 'الإمتاع والمؤانسة', 'الصديق الحقيقي قريب منك حتى كأنه نفسك، يشبهك في الفكر والشعور، لكنه شخص آخر.'],
            ['literature', 'الظلم مؤذن بخراب العمران', 'ابن خلدون', 'المقدمة', 'الظلم إعلان بخراب الدول والمجتمعات، فحين ينتشر الظلم يفقد الناس الأمان ويتوقفون عن العمل والبناء فتنهار الحضارة.'],
            ['theater', 'All the world’s a stage, and all the men and women merely players.', 'William Shakespeare', 'As You Like It', 'يشبّه شكسبير العالم بمسرح كبير، والناس ممثلين يؤدّي كل منهم أدواره في مراحل حياته ثم يخرج من المشهد.'],
            ['theater', 'Life’s but a walking shadow, a poor player that struts and frets his hour upon the stage, and then is heard no more.', 'William Shakespeare', 'Macbeth', 'يقولها ماكبث بعد أن خسر كل شيء: الحياة ظل عابر، كممثل ضعيف يتباهى ويقلق ساعته على المسرح ثم لا يُسمع له صوت بعدها.'],
            ['theater', 'The play’s the thing wherein I’ll catch the conscience of the king.', 'William Shakespeare', 'Hamlet', 'يخطط هاملت لعرض مسرحية تشبه جريمة قتل أبيه، ليراقب الملك وهو يشاهدها فيكشف ضميرُه حقيقتَه.'],
            ['theater', 'Some are born great, some achieve greatness, and some have greatness thrust upon them.', 'William Shakespeare', 'Twelfth Night', 'العظمة تأتي بثلاث طرق: بعض الناس يولد عظيماً، وبعضهم يصنع عظمته بجهده، وبعضهم تُفرض عليه العظمة دون أن يسعى لها.'],
            ['theater', 'We are such stuff as dreams are made on, and our little life is rounded with a sleep.', 'William Shakespeare', 'The Tempest', 'نحن مصنوعون من مادة الأحلام، وحياتنا القصيرة يحيط بها النوم؛ تأمّل في قِصر الحياة وأنها تمرّ كالحلم.'],
            ['theater', 'What’s in a name? That which we call a rose by any other name would smell as sweet.', 'William Shakespeare', 'Romeo and Juliet', 'تقولها جولييت عن روميو: الاسم لا يغيّر حقيقة الشيء، فالوردة تبقى عطرة مهما كان اسمها، وقيمة الإنسان فيه لا في اسم عائلته.'],
            ['theater', 'We are all in the gutter, but some of us are looking at the stars.', 'Oscar Wilde', 'Lady Windermere’s Fan', 'كلنا نعيش في واقع صعب أو ناقص، لكن الفرق أن بعضنا يرفع رأسه وينظر إلى النجوم ويتمسك بالأمل والطموح.'],
            ['literature', 'It was the best of times, it was the worst of times.', 'Charles Dickens', 'A Tale of Two Cities', 'افتتاحية رواية "قصة مدينتين" عن زمن الثورة الفرنسية: العصر الواحد قد يجمع الأمل واليأس، فيكون أفضل الأزمنة وأسوأها في الوقت نفسه.'],
            ['literature', 'I declare after all there is no enjoyment like reading!', 'Jane Austen', 'Pride and Prejudice', 'لا متعة تعادل متعة القراءة. وفي الرواية تقولها شخصية لا تحب القراءة في الحقيقة، فتسخر أوستن بذكاء ممن يتظاهرون بالثقافة.'],
            ['literature', 'I am no bird; and no net ensnares me: I am a free human being with an independent will.', 'Charlotte Brontë', 'Jane Eyre', 'تقولها جين آير لتؤكد أنها ليست طائراً يُحبس في قفص، بل إنسانة حرة لها إرادتها وقرارها.'],
            ['literature', 'Call me Ishmael.', 'Herman Melville', 'Moby-Dick', 'أشهر افتتاحية في الأدب الأمريكي، يقدّم فيها الراوي نفسه باسم إسماعيل قبل أن يحكي رحلته في البحر خلف الحوت الأبيض.'],
            ['literature', 'We’re all mad here.', 'Lewis Carroll', 'Alice’s Adventures in Wonderland', 'يقولها القط شيشاير لأليس: في بلاد العجائب الجميع مجانين، أي أن لكل عالم منطقه الغريب، وأن الاختلاف شيء طبيعي.'],
            ['literature', 'Beware; for I am fearless, and therefore powerful.', 'Mary Shelley', 'Frankenstein', 'يقولها مخلوق فرانكنشتاين لصانعه: من لا يخاف شيئاً لم يعد عنده ما يخسره، ولذلك صار قوياً وخطيراً.'],
            ['literature', 'A woman must have money and a room of her own if she is to write fiction.', 'Virginia Woolf', 'A Room of One’s Own', 'تقول وولف إن المرأة لكي تبدع في الكتابة تحتاج إلى استقلال مادي ومكان خاص بها، أي إلى الحرية والوقت والهدوء.'],
            ['literature', 'There is no such thing as a moral or an immoral book. Books are well written, or badly written. That is all.', 'Oscar Wilde', 'The Picture of Dorian Gray', 'يرى وايلد أن الكتاب لا يُحكم عليه بأنه أخلاقي أو غير أخلاقي، بل بجودة كتابته فقط: إما مكتوب بإتقان أو بضعف.'],
            ['literature', 'Reading maketh a full man; conference a ready man; and writing an exact man.', 'Francis Bacon', 'Of Studies', 'القراءة تملأ عقل الإنسان بالمعرفة، والحوار يجعله سريع البديهة، والكتابة تجعله دقيقاً في أفكاره.'],
            ['literature', 'Some books are to be tasted, others to be swallowed, and some few to be chewed and digested.', 'Francis Bacon', 'Of Studies', 'الكتب أنواع: بعضها يكفي أن تتذوقه بقراءة سريعة، وبعضها تقرؤه كاملاً، وقليل منها يستحق أن تقرأه بتمعّن وتفكّر فيه طويلاً.'],
            ['literature', 'The mass of men lead lives of quiet desperation.', 'Henry David Thoreau', 'Walden', 'أغلب الناس يعيشون حياة فيها يأس صامت، يكررون أيامهم دون أن يعيشوا أحلامهم، ولا يبوحون بذلك.'],
            ['literature', 'To be great is to be misunderstood.', 'Ralph Waldo Emerson', 'Self-Reliance', 'العظماء غالباً لا يفهمهم الناس في زمانهم، فلا تخشَ أن يُساء فهمك إذا كنت صادقاً مع نفسك وأفكارك.'],
            ['poetry', 'Hope is the thing with feathers that perches in the soul.', 'Emily Dickinson', '', 'تشبّه الأمل بطائر صغير يسكن الروح، يغني بلا توقف حتى في أصعب الأوقات ولا يطلب شيئاً في المقابل.'],
            ['poetry', 'A thing of beauty is a joy for ever.', 'John Keats', 'Endymion', 'الشيء الجميل يبقى مصدر فرح دائم، لا يذبل جماله ولا ينتهي أثره في النفس.'],
            ['poetry', 'Beauty is truth, truth beauty.', 'John Keats', 'Ode on a Grecian Urn', 'يرى كيتس أن الجمال والحقيقة وجهان لشيء واحد؛ فكل جميل صادق، وكل صادق جميل.'],
            ['poetry', 'Poetry is the spontaneous overflow of powerful feelings.', 'William Wordsworth', 'Preface to Lyrical Ballads', 'الشعر عند وردزورث مشاعر قوية تفيض من الشاعر بصدق وعفوية، دون تكلّف أو تصنّع.'],
            ['poetry', 'Poets are the unacknowledged legislators of the world.', 'Percy Bysshe Shelley', 'A Defence of Poetry', 'يرى شيلي أن الشعراء يشكّلون أفكار الناس وقيمهم ويغيّرون العالم، حتى لو لم يعترف أحد بدورهم هذا.'],
            ['poetry', 'To see a World in a Grain of Sand, and a Heaven in a Wild Flower.', 'William Blake', 'Auguries of Innocence', 'أن ترى العالم كله في حبة رمل، والجنة في زهرة برية؛ أي أن تتأمل الأشياء الصغيرة لترى فيها عظمة الخلق وجماله.'],
            ['poetry', 'To strive, to seek, to find, and not to yield.', 'Alfred, Lord Tennyson', 'Ulysses', 'آخر بيت في قصيدة يوليسيس: أن تكافح وتبحث وتجد ولا تستسلم أبداً، حتى مع تقدّم العمر.'],
            ['poetry', 'The mind is its own place, and in itself can make a heaven of hell, a hell of heaven.', 'John Milton', 'Paradise Lost', 'العقل يصنع واقع الإنسان؛ فبنظرته يستطيع أن يحوّل الجحيم إلى جنة، أو يحوّل الجنة إلى جحيم.'],
            ['poetry', 'All that we see or seem is but a dream within a dream.', 'Edgar Allan Poe', 'A Dream Within a Dream', 'يتساءل بو هل كل ما نراه ونعيشه حقيقي، أم أنه مجرد حلم داخل حلم آخر، تعبيراً عن حيرته أمام الزمن الذي يتسرب من بين يديه.'],
            ['poetry', 'Do I contradict myself? Very well then I contradict myself, I am large, I contain multitudes.', 'Walt Whitman', 'Song of Myself', 'يعترف ويتمان بأنه قد يناقض نفسه، ويرى ذلك طبيعياً لأن الإنسان واسع يحمل في داخله أفكاراً ومشاعر كثيرة ومتنوعة.'],
        ];
    }
